from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter()

PAGE = r"""
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ENT AI Tutor</title>
<style>
:root{color-scheme:dark;--bg:#0c1222;--panel:#151f35;--line:#2a3855;--text:#eef3ff;--muted:#a4b1ca;--accent:#86a3ff;--good:#63d6a4;--bad:#ff8798}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#1b2a50,var(--bg) 60%);color:var(--text);font:16px/1.5 system-ui,sans-serif}
header{border-bottom:1px solid var(--line);padding:16px 22px;display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;background:#0c1222ee}
main{max-width:950px;margin:32px auto;padding:0 16px 50px}.brand{font-weight:850;font-size:20px}.brand span,h1 span{color:var(--accent)}
h1{font-size:clamp(32px,5vw,48px);line-height:1.08;letter-spacing:-1px}h2{margin:0 0 8px}p{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px;margin:14px 0}
label{display:block;color:var(--muted);font-size:13px;margin:12px 0 5px}input,select{width:100%;background:#0b1427;color:var(--text);padding:11px;border:1px solid var(--line);border-radius:9px;font:inherit}button{padding:11px 15px;border:0;border-radius:9px;background:var(--accent);color:#10182e;font:inherit;font-weight:750;cursor:pointer;margin:12px 8px 0 0}button.secondary{background:#202e4b;color:var(--text)}.hidden{display:none!important}.muted{font-size:13px;color:var(--muted)}
#notice{padding:12px;border-radius:9px;background:#20304e;margin:14px 0}#notice.error{background:#492332}.question{background:#0f192d;border:1px solid var(--line);border-radius:12px;padding:16px;margin:14px 0}.qmeta{display:flex;justify-content:space-between;color:var(--muted);font-size:12px}.qtext{font-size:17px;font-weight:650;margin:10px 0;white-space:pre-wrap}.option{display:flex;gap:10px;padding:9px;border:1px solid var(--line);border-radius:8px;margin:7px 0;cursor:pointer}.option input{width:auto;margin-top:5px;accent-color:var(--accent)}.match{display:grid;grid-template-columns:1fr 100px;gap:10px;align-items:center;margin:8px 0}.score{font-size:36px;font-weight:850}.review{padding:13px 0;border-top:1px solid var(--line)}.good{color:var(--good)}.bad{color:var(--bad)}footer{text-align:center;color:var(--muted);font-size:12px;padding:20px}
@media(max-width:650px){.grid{grid-template-columns:1fr}.panel{padding:16px}main{margin-top:16px}}
</style></head><body>
<header><div class="brand">ENT <span>AI</span> Tutor</div><div><span id="status" class="muted">Подготовка к ЕНТ</span> <button id="logout" class="secondary hidden">Выйти</button></div></header>
<main><p class="muted">ТВОЯ ПОДГОТОВКА — В ОДНОМ МЕСТЕ</p><h1>Готовься умнее.<br><span>Расти с каждой попыткой.</span></h1><p>Практические вопросы, мгновенная проверка и разбор ответов.</p>
<div id="notice" class="hidden"></div>
<section id="auth" class="grid">
<div class="panel"><h2>Войти</h2><form id="login"><label>Email</label><input id="email" type="email" required><label>Пароль</label><input id="password" type="password" required><button>Войти в аккаунт</button></form></div>
<div class="panel"><h2>Создать аккаунт</h2><form id="register"><label>Имя пользователя</label><input id="username" required minlength="2"><label>Email</label><input id="newemail" type="email" required><label>Пароль (минимум 8 символов)</label><input id="newpassword" type="password" required minlength="8"><button>Зарегистрироваться</button></form></div>
</section>
<section id="dashboard" class="panel hidden"><h2>Полный пробный ЕНТ</h2><p>120 вопросов · 140 баллов · 240 минут. Комбинация профильных предметов: Информатика + Математика.</p><button id="start">Начать полный пробный</button></section>
<section id="test" class="panel hidden"><div class="qmeta"><span id="subjectLabel">ИнфоМат · Полный пробный ЕНТ</span><span><b id="timer">04:00:00</b> · <span id="qcount"></span></span></div><h2>Полный пробный ЕНТ</h2><form id="answers"><div id="questions"></div><button id="submit">Завершить и проверить</button><button type="button" id="cancel" class="secondary">Отмена</button></form></section>
<section id="results" class="panel hidden"><p class="muted">РЕЗУЛЬТАТ ПОПЫТКИ</p><h2>Тренировка завершена</h2><div id="score" class="score"></div><p id="scoretext"></p><button id="again">Следующая тренировка</button><h2 style="margin-top:24px">Разбор ответов</h2><div id="review"></div></section>
</main><footer>ENT AI Tutor · Учебный проект</footer>
<script>
const $=id=>document.getElementById(id);let token=localStorage.getItem("ent_ai_token")||"",sessionId=null,qs=[],subject="",timerHandle=null,expiresAt=null,submitting=false;
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function msg(s,error=false){$("notice").textContent=s;$("notice").classList.toggle("hidden",!s);$("notice").classList.toggle("error",error)}
function show(id){["auth","dashboard","test","results"].forEach(x=>$(x).classList.toggle("hidden",x!==id))}
function authUI(){ $("status").textContent=token?"Ты вошёл в систему":"Подготовка к ЕНТ";$("logout").classList.toggle("hidden",!token);show(token?"dashboard":"auth")}
async function api(url,opts={}){let h=new Headers(opts.headers||{});if(token)h.set("Authorization","Bearer "+token);if(opts.body&&!(opts.body instanceof URLSearchParams))h.set("Content-Type","application/json");let r=await fetch(url,{...opts,headers:h}),t=await r.text(),d;try{d=t?JSON.parse(t):null}catch{d=t}if(!r.ok)throw Error(d?.detail||`Ошибка ${r.status}`);return d}
$("register").onsubmit=async e=>{e.preventDefault();msg("");try{let u={username:$("username").value.trim(),email:$("newemail").value.trim(),password:$("newpassword").value};await api("/register",{method:"POST",body:JSON.stringify(u)});$("email").value=u.email;$("password").value=u.password;msg("Аккаунт создан. Теперь войди.");}catch(x){msg("Регистрация: "+x.message,true)}};
$("login").onsubmit=async e=>{e.preventDefault();msg("");try{let d=await api("/login",{method:"POST",body:new URLSearchParams({username:$("email").value.trim(),password:$("password").value})});token=d.access_token;localStorage.setItem("ent_ai_token",token);authUI();msg("Вход выполнен.");}catch(x){msg("Вход: "+x.message,true)}};
$("logout").onclick=()=>{token="";localStorage.removeItem("ent_ai_token");authUI();msg("Ты вышел из аккаунта.")};
function render(q,i){let type=(q.question_type||"single").toLowerCase(),html="";
if(type==="single"||type==="multiple"){html=["A","B","C","D","E","F"].filter(l=>q["option_"+l.toLowerCase()]).map(l=>`<label class="option"><input type="${type==="multiple"?"checkbox":"radio"}" name="q${q.id}" value="${l}"><span><b>${l}.</b> ${esc(q["option_"+l.toLowerCase()])}</span></label>`).join("")}
else if(type==="matching"){html=[["A",q.matching_a],["B",q.matching_b]].filter(x=>x[1]).map(([l,t])=>`<div class="match"><span>${l}. ${esc(t)}</span><select name="q${q.id}_${l}"><option value="">—</option>${[1,2,3,4].map(n=>`<option value="${n}">${n}. ${esc(q["matching_"+n]||"")}</option>`).join("")}</select></div>`).join("")}
const sectionNames={mathematical_literacy:"Математическая грамотность",reading_literacy:"Грамотность чтения",kazakhstan_history:"История Казахстана",profile:q.subject==="Computer Science"?"Профильный предмет: Информатика":"Профильный предмет: Математика"};const section=(i===0||qs[i-1]?.ent_section!==q.ent_section)?`<h2 style="margin-top:28px">${esc(sectionNames[q.ent_section]||q.subject)}</h2>`:"";const context=(q.context_id&&q.context_content&&(!i||qs[i-1]?.context_id!==q.context_id))?`<article class="question"><div class="qmeta"><span>Общий контекст</span><span>${esc(q.context_title||"Прочитай текст")}</span></div><div class="qtext" style="font-weight:450">${esc(q.context_content)}</div></article>`:"";return section+context+`<article class="question"><div class="qmeta"><span>Вопрос ${i+1} из 120</span><span>${type==="multiple"?"Несколько ответов":type==="matching"?"Сопоставление":"Один ответ"}</span></div><div class="qtext">${esc(q.question)}</div>${html}</article>`}
function stopTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null}}
function updateTimer(){if(!expiresAt)return;let left=Math.max(0,Math.floor((expiresAt-Date.now())/1000));let h=String(Math.floor(left/3600)).padStart(2,"0"),m=String(Math.floor((left%3600)/60)).padStart(2,"0"),s=String(left%60).padStart(2,"0");$("timer").textContent=`${h}:${m}:${s}`;if(left<=0&&!submitting){msg("Время закончилось. Отправляем ответы…");$("answers").requestSubmit()}}
$("start").onclick=async()=>{msg("");$("start").disabled=true;try{let s=await api("/start-test?test_type=ent_full",{method:"POST"});sessionId=s.session_id;expiresAt=new Date(s.expires_at.endsWith("Z")?s.expires_at:s.expires_at+"Z").getTime();qs=await api("/ent-test?profile_subject=Computer%20Science&profile_subject_2=Mathematics");if(!Array.isArray(qs)||qs.length!==120)throw Error(`Ожидалось 120 вопросов, получено ${qs?.length||0}.`);$("qcount").textContent=qs.length+" вопросов · максимум 140 баллов";$("questions").innerHTML=qs.map(render).join("");show("test");msg("Пробный начат. Ответы можно оставлять пустыми; за них будет 0 баллов.");updateTimer();timerHandle=setInterval(updateTimer,1000)}catch(x){sessionId=null;msg(x.message,true)}finally{$("start").disabled=false}};
$("answers").onsubmit=async e=>{e.preventDefault();if(!sessionId||submitting)return;submitting=true;stopTimer();let button=$("submit");button.disabled=true;try{let data=qs.map(q=>{let type=(q.question_type||"single").toLowerCase(),answer="";if(type==="multiple")answer=[...document.querySelectorAll(`input[name="q${q.id}"]:checked`)].map(x=>x.value).sort().join(",");else if(type==="matching")answer=["A","B"].map(l=>{let x=document.querySelector(`[name="q${q.id}_${l}"]`);return x?.value?`${l}:${x.value}`:""}).filter(Boolean).join(",");else answer=document.querySelector(`input[name="q${q.id}"]:checked`)?.value||"";return{question_id:q.id,answer}});let r=await api(`/submit-test?session_id=${sessionId}`,{method:"POST",body:JSON.stringify(data)});$("score").textContent=`${r.score} / ${r.max_score}`;$("scoretext").textContent=`${r.percentage}% · Проверено вопросов: ${r.total_questions}`;let map=new Map(qs.map(q=>[q.id,q]));$("review").innerHTML=r.results.map((x,i)=>{let q=map.get(x.question_id)||{},ok=x.points_earned===x.max_points;return `<div class="review"><div class="${ok?"good":"bad"}">Вопрос ${i+1}: ${x.points_earned}/${x.max_points} балла</div><div class="qtext">${esc(q.question)}</div><p>Твой ответ: <b>${esc(x.user_answer||"—")}</b><br>Правильный ответ: <b>${esc(x.correct_answer)}</b></p><p>${esc(x.explanation||"Объяснение не добавлено.")}</p></div>`}).join("");sessionId=null;expiresAt=null;submitting=false;show("results");msg("Результат сохранён.")}catch(x){submitting=false;msg(x.message,true)}finally{button.disabled=false}};
$("cancel").onclick=()=>{stopTimer();sessionId=null;expiresAt=null;submitting=false;qs=[];show("dashboard");msg("Тест отменён.")};$("again").onclick=()=>{stopTimer();sessionId=null;expiresAt=null;submitting=false;show("dashboard");msg("")};authUI();
</script></body></html>
"""


@router.get("/", response_class=HTMLResponse, include_in_schema=False)
def home():
    return HTMLResponse(PAGE)
